#!/usr/bin/env python3

# ----------------------------------------------------------------------
# Usage: python read_csv_csi.py csi_capture_*.csv
# Reads CSV files generated by live_monitor.py --capture-mode complex
# ----------------------------------------------------------------------

import sys
import numpy as np
import pandas as pd
from pathlib import Path

# ------------------------------------------------------------------
# Configuration
# ------------------------------------------------------------------

# These are derived from the CSV structure
# Each packet has: ts, seq_num, core, spatial_stream, then I/Q pairs
# For 80MHz: 256 subcarriers * 2 (I and Q) = 512 columns
# For 40MHz: 128 subcarriers * 2 = 256 columns
# For 20MHz: 64 subcarriers * 2 = 128 columns

# ------------------------------------------------------------------


def extract_csi_from_csv(csv_file):
    """
    Read CSI data from live_monitor.py CSV output (complex mode)
    Returns complex CSI array and metadata
    """
    
    print(f"Reading CSV file: {csv_file}")
    
    # Read the CSV
    df = pd.read_csv(csv_file)
    
    print(f"CSV shape: {df.shape} rows x {df.shape[1]} columns")
    
    # Extract metadata columns
    timestamps = df['ts'].values
    seq_nums = df['seq_num'].values
    cores = df['core'].values
    spatial_streams = df['spatial_stream'].values
    
    # Identify complex columns (I and Q pairs)
    # Column naming: sc0_re, sc0_im, sc1_re, sc1_im, ...
    complex_cols = [col for col in df.columns if col not in ['ts', 'seq_num', 'core', 'spatial_stream']]
    
    # Determine number of subcarriers
    n_sc = len(complex_cols) // 2
    print(f"Number of subcarriers detected: {n_sc}")
    
    # Extract I and Q values and build complex numbers
    all_complex = []
    
    for idx in range(len(df)):
        row = df.iloc[idx]
        
        # Extract I and Q for each subcarrier
        i_vals = []
        q_vals = []
        
        for sc in range(n_sc):
            i_vals.append(row[f'sc{sc}_re'])
            q_vals.append(row[f'sc{sc}_im'])
        
        # Convert to complex
        complex_csi = np.array(i_vals, dtype=np.float64) + 1j * np.array(q_vals, dtype=np.float64)
        all_complex.append(complex_csi)
    
    # Convert to numpy array
    csi_array = np.array(all_complex)
    
    # Extract metadata from first packet
    metadata = {
        'first_ts': timestamps[0],
        'last_ts': timestamps[-1],
        'duration': timestamps[-1] - timestamps[0],
        'n_packets': len(df),
        'n_subcarriers': n_sc,
        'seq_first': seq_nums[0],
        'seq_last': seq_nums[-1],
        'core': cores[0] if len(np.unique(cores)) == 1 else np.unique(cores).tolist(),
        'spatial_stream': spatial_streams[0] if len(np.unique(spatial_streams)) == 1 else np.unique(spatial_streams).tolist(),
    }
    
    return csi_array, metadata


def analyze_csi(csi_array, metadata):
    """
    Analyze CSI data and print statistics similar to read_pcap.py
    """
    
    n_packets, n_subcarriers = csi_array.shape
    
    print("\n" + "="*60)
    print("CSI Analysis from CSV")
    print("="*60)
    
    # ------------------------------------------------------------------
    # Packet statistics
    # ------------------------------------------------------------------
    
    print(f"\nPacket Statistics")
    print("-" * 40)
    print(f"Total packets     = {n_packets}")
    print(f"Subcarriers       = {n_subcarriers}")
    print(f"Duration          = {metadata['duration']:.3f} seconds")
    print(f"Average rate      = {n_packets / metadata['duration']:.2f} packets/sec")
    print(f"Sequence numbers  = {metadata['seq_first']} to {metadata['seq_last']}")
    print(f"Core(s)           = {metadata['core']}")
    print(f"Spatial stream(s) = {metadata['spatial_stream']}")
    
    # ------------------------------------------------------------------
    # Complex value statistics (like int16 stats in read_pcap.py)
    # ------------------------------------------------------------------
    
    # Flatten all complex values to get I and Q separately
    all_i = csi_array.real.flatten()
    all_q = csi_array.imag.flatten()
    
    print(f"\nComplex Value Statistics")
    print("-" * 40)
    print(f"Min I value = {all_i.min():.2f}")
    print(f"Max I value = {all_i.max():.2f}")
    print(f"Min Q value = {all_q.min():.2f}")
    print(f"Max Q value = {all_q.max():.2f}")
    print(f"Number of zeros (I=0 and Q=0) = {np.sum((all_i == 0) & (all_q == 0))}")
    print(f"Total samples (complex) = {len(csi_array.flatten())}")
    
    # Magnitude statistics
    magnitudes = np.abs(csi_array)
    print(f"\nMagnitude Statistics")
    print("-" * 40)
    print(f"Min magnitude = {magnitudes.min():.2f}")
    print(f"Max magnitude = {magnitudes.max():.2f}")
    print(f"Mean magnitude = {magnitudes.mean():.2f}")
    print(f"Std magnitude = {magnitudes.std():.2f}")
    
    # Phase statistics (in degrees)
    phases = np.angle(csi_array, deg=True)
    print(f"\nPhase Statistics (degrees)")
    print("-" * 40)
    print(f"Min phase = {phases.min():.2f}°")
    print(f"Max phase = {phases.max():.2f}°")
    print(f"Mean phase = {phases.mean():.2f}°")
    print(f"Std phase = {phases.std():.2f}°")
    
    # ------------------------------------------------------------------
    # Strongest 15 subcarriers (like read_pcap.py)
    # Uses packet 100 if available, otherwise last packet
    # ------------------------------------------------------------------
    
    idx_pkt = min(99, n_packets - 1)
    
    # Magnitudes for the selected packet
    pkt_magnitudes = magnitudes[idx_pkt]
    
    # Get strongest 15 subcarriers
    strongest_idx = np.argsort(pkt_magnitudes)[::-1][:15]
    
    print(f"\n15 Strongest Subcarriers (packet {idx_pkt + 1} of {n_packets})")
    print("-" * 60)
    print(f"{'Subcarrier':<12} {'Magnitude':<12} {'I':<12} {'Q':<12} {'Phase (°)':<12}")
    print("-" * 60)
    
    for i in strongest_idx:
        complex_val = csi_array[idx_pkt, i]
        phase_deg = np.angle(complex_val, deg=True)
        print(f"{i:>5}      {pkt_magnitudes[i]:>10.2f}  {complex_val.real:>10.2f}  {complex_val.imag:>10.2f}  {phase_deg:>10.2f}°")
    
    # ------------------------------------------------------------------
    # Subcarrier statistics over time
    # ------------------------------------------------------------------
    
    print(f"\nSubcarrier Statistics Over All Packets")
    print("-" * 60)
    
    # Mean magnitude per subcarrier
    mean_mag_per_sc = np.mean(magnitudes, axis=0)
    std_mag_per_sc = np.std(magnitudes, axis=0)
    
    # Find most and least stable subcarriers
    most_stable_idx = np.argmin(std_mag_per_sc)
    least_stable_idx = np.argmax(std_mag_per_sc)
    
    print(f"Most stable subcarrier (lowest std): {most_stable_idx} (std={std_mag_per_sc[most_stable_idx]:.2f})")
    print(f"Least stable subcarrier (highest std): {least_stable_idx} (std={std_mag_per_sc[least_stable_idx]:.2f})")
    print(f"Mean magnitude across all subcarriers: {mean_mag_per_sc.mean():.2f}")
    print(f"Std of mean magnitudes across subcarriers: {mean_mag_per_sc.std():.2f}")
    
    # ------------------------------------------------------------------
    # Motion detection (similar to live_monitor.py's motion score)
    # ------------------------------------------------------------------
    
    # Calculate motion score: mean of per-subcarrier std / mean magnitude
    if n_packets > 10:
        per_sc_std = np.std(magnitudes, axis=0)
        mean_amp = np.mean(magnitudes)
        motion_score = np.mean(per_sc_std) / mean_amp if mean_amp > 0 else 0
        
        print(f"\nMotion Detection")
        print("-" * 40)
        print(f"Motion score = {motion_score:.5f}")
        print(f"(Higher values indicate more movement/variation)")
        
        # Baseline comparison (first 100 packets vs rest)
        if n_packets > 200:
            baseline_mag = magnitudes[:100]
            test_mag = magnitudes[100:]
            
            baseline_score = np.mean(np.std(baseline_mag, axis=0)) / np.mean(baseline_mag)
            test_score = np.mean(np.std(test_mag, axis=0)) / np.mean(test_mag)
            
            ratio = test_score / baseline_score if baseline_score > 0 else 0
            print(f"Baseline motion score (first 100 pkts): {baseline_score:.5f}")
            print(f"Test motion score (remaining pkts): {test_score:.5f}")
            print(f"Ratio (test/baseline): {ratio:.3f}x")
            if ratio > 1.5:
                print("  ** MOTION / CHANGE DETECTED **")
    
    # ------------------------------------------------------------------
    # Summary
    # ------------------------------------------------------------------
    
    print("\n" + "="*60)
    print("Analysis Complete")
    print("="*60)


def main():
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} csi_capture_*.csv")
        print("\nThis script reads CSV files generated by:")
        print("  live_monitor.py --capture-mode complex")
        print("\nExample:")
        print("  python read_csv_csi.py output/csi_capture_20240101_120000.csv")
        sys.exit(1)
    
    csv_file = sys.argv[1]
    
    if not Path(csv_file).exists():
        print(f"Error: File '{csv_file}' not found!")
        sys.exit(1)
    
    try:
        # Extract CSI data from CSV
        csi_array, metadata = extract_csi_from_csv(csv_file)
        
        # Analyze the data
        analyze_csi(csi_array, metadata)
        
    except Exception as e:
        print(f"Error processing CSV file: {e}")
        print("\nMake sure the CSV was generated with --capture-mode complex")
        print("The CSV should have columns: ts, seq_num, core, spatial_stream, sc0_re, sc0_im, ...")
        sys.exit(1)


if __name__ == "__main__":
    main()